/**
 * Bulk-safe trigger for Contact.
 *
 * The trigger itself contains no SOQL and no DML. All logic is delegated to
 * ContactTriggerHandler, which processes each batch of records in bulk so that a
 * single insert or update of up to 200 contacts costs at most 2 SOQL queries and
 * at most 1 DML statement across the before and after contexts together.
 *
 * Behaviour (identical to the original trigger):
 *   before insert : defaults MailingCountry and LeadSource from the related Account.
 *   before update : defaults MailingCountry from the related Account.
 *   after insert  : if an Account has no Phone, the first new contact of that
 *                   account (in trigger order) that has a Phone sets it.
 */
trigger ContactTrigger on Contact (before insert, before update, after insert) {
    if (Trigger.isBefore && Trigger.isInsert) {
        ContactTriggerHandler.handleBeforeInsert(Trigger.new);
    } else if (Trigger.isBefore && Trigger.isUpdate) {
        ContactTriggerHandler.handleBeforeUpdate(Trigger.new);
    } else if (Trigger.isAfter && Trigger.isInsert) {
        ContactTriggerHandler.handleAfterInsert(Trigger.new);
    }
}
