/**
 * Handler for ContactTrigger.
 *
 * All SOQL and DML for the trigger lives here and is fully bulkified:
 *   before insert / before update : 1 SOQL query for the whole batch, no DML.
 *   after insert                  : 1 SOQL query for the whole batch, 1 DML statement.
 *
 * Invoked from a trigger this class runs in system mode (inherited sharing),
 * which matches the data access of the original inline trigger logic.
 *
 * Behaviour is preserved exactly, including the rule that when several new
 * contacts of the same Account have a Phone and the Account has none, the
 * first such contact in trigger order sets the Account's Phone.
 */
public inherited sharing class ContactTriggerHandler {

    /**
     * before insert: defaults MailingCountry and LeadSource from the related
     * Account. 1 SOQL query for the whole batch, no DML.
     */
    public static void handleBeforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    /**
     * before update: defaults MailingCountry from the related Account.
     * 1 SOQL query for the whole batch, no DML.
     */
    public static void handleBeforeUpdate(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, false);
    }

    /**
     * after insert: for every new contact that has an AccountId and a
     * non-blank Phone, if the Account's Phone is blank it is set from that
     * contact. When several contacts of the same Account qualify, the first
     * one in trigger order wins. 1 SOQL query and 1 DML statement for the
     * whole batch.
     */
    public static void handleAfterInsert(List<Contact> newContacts) {
        propagateFirstContactPhoneToAccount(newContacts);
    }

    /**
     * Shared before insert / before update logic.
     *
     * One query for all distinct AccountIds in the batch, then in-memory field
     * assignment on the trigger records (no DML is needed in a before context).
     *
     * Mirrors the original per-contact lookup:
     *   - MailingCountry is defaulted from Account.BillingCountry when blank.
     *   - On insert only, LeadSource is defaulted from Account.AccountSource
     *     when blank.
     */
    private static void applyAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(c.AccountId);
            if (account == null) {
                // Defensive: skip if the Account could not be retrieved instead
                // of failing the whole batch.
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = account.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = account.AccountSource;
            }
        }
    }

    /**
     * After insert logic: copies the first qualifying contact's Phone onto a
     * phone-less Account, with at most one bulk update.
     *
     * accountsAlreadyAssigned preserves the original in-transaction behaviour:
     * the original loop re-queried the Account after each DML statement, so
     * once the first contact had set the Account's Phone, subsequent contacts
     * of the same Account saw a non-blank Phone and did nothing. Hence the
     * first contact in trigger order wins.
     */
    private static void propagateFirstContactPhoneToAccount(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        Set<Id> accountsAlreadyAssigned = new Set<Id>();

        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            if (accountsAlreadyAssigned.contains(c.AccountId)) {
                // A previous contact in this batch already set this Account's
                // Phone; the first contact in trigger order wins.
                continue;
            }
            Account account = accountsById.get(c.AccountId);
            if (account == null || String.isNotBlank(account.Phone)) {
                // Account not retrievable, or it already has a Phone.
                continue;
            }
            account.Phone = c.Phone;
            accountsToUpdate.add(account);
            accountsAlreadyAssigned.add(c.AccountId);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
