/**
 * Queueable job that re-rates Accounts (Rating = Hot / Warm / Cold) from their
 * AnnualRevenue, in self-chaining batches so that up to 50,000 Accounts can be
 * re-rated on demand (a button calls AccountScoringJob.start(accountIds)).
 *
 * Rating rules:
 *   AnnualRevenue >= 1,000,000                -> 'Hot'
 *   AnnualRevenue >= 100,000 (and < 1,000,000) -> 'Warm'
 *   anything else, including blank             -> 'Cold'
 *
 * Chain design:
 *  - Each execution processes at most 200 Accounts: the first 200 Ids of its list.
 *    It uses exactly one SOQL query and one DML statement per execution.
 *  - If Ids remain, the execution enqueues a new AccountScoringJob seeded with the
 *    remaining Ids, so the jobs form a chain that eventually drains the whole list.
 *  - Chaining is unconditional: it is deliberately NOT skipped while a test is
 *    running (no Test.isRunningTest() gating), so a single Apex test can verify
 *    the whole chain by wrapping AccountScoringJob.start(ids) inside
 *    Test.startTest() / Test.stopTest().
 *
 * Per-execution governor-limit footprint: 1 SOQL query, 1 DML statement, and at
 * most one child job enqueued (Queueable allows exactly one child per execution).
 */
public inherited sharing class AccountScoringJob implements Queueable {

    /** Maximum number of Accounts processed by a single execution of the chain. */
    private static final Integer BATCH_SIZE = 200;

    /** Account Ids still to be processed; the first BATCH_SIZE Ids are handled per execution. */
    private List<Id> accountIds;

    /**
     * Creates one link of the scoring chain.
     *
     * @param accountIds Account Ids to rate, in processing order. May be null or
     *                   empty; such a job simply does nothing when executed.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Rates the first (up to) 200 Accounts of this job's Id list, then enqueues the
     * next link of the chain if any Ids remain.
     *
     * @param context Queueable context supplied by the platform; may be null when
     *                execute is invoked directly on a job instance (e.g. in tests).
     */
    public void execute(QueueableContext context) {
        // Nothing to do; also keeps direct execute(null) calls safe and limit-free.
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Slice by position in the Id list (not by query results) so deleted or
        // inaccessible Accounts cannot shift the processing window.
        Integer batchEnd = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> batchIds = new List<Id>(accountIds.subList(0, batchEnd));

        // Exactly one SOQL query for this execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        // Derive the new Rating from AnnualRevenue.
        for (Account acc : accounts) {
            acc.Rating = ratingForRevenue(acc.AnnualRevenue);
        }

        // Exactly one DML statement for this execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        // Chain the remainder: enqueue exactly one child job holding the
        // still-unprocessed Ids. The remaining Ids are copied into a plain List so
        // the job's serialized state is a self-contained List<Id>.
        if (batchEnd < accountIds.size()) {
            List<Id> remainingIds = new List<Id>(accountIds.subList(batchEnd, accountIds.size()));
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    /**
     * Maps AnnualRevenue to a Rating per marketing's rules.
     *
     * @param annualRevenue the Account's AnnualRevenue; may be null.
     * @return 'Hot' (>= 1,000,000), 'Warm' (>= 100,000), otherwise 'Cold'.
     */
    private static String ratingForRevenue(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue != null && annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }

    /**
     * Enqueues the first job of the chain.
     *
     * @param accountIds Account Ids to rate; a null or empty list enqueues nothing.
     * @return the Job Id (AsyncApexJob Id) of the first queueable, or null when
     *         there is nothing to process.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
