/**
 * @description Schedulable purge job for integration logs stored in
 *              FB_Integration_Log__c.
 *
 *              Retention rules:
 *              - Any log created more than 30 days ago is deleted, unless
 *              - its Level__c is 'ERROR' (case-insensitive per SOQL semantics).
 *                ERROR logs are retained until they are more than 180 days old.
 *                A blank Level__c is treated as a non-ERROR log (30-day rule).
 *
 *              The class runs in system context (without sharing) so record
 *              sharing can never leave expired logs behind. The user who
 *              schedules the job must have Delete access on
 *              FB_Integration_Log__c. Deleted records remain in the recycle
 *              bin for the standard 15-day recovery window.
 */
public without sharing class LogPurgeJob implements Schedulable {

    /** Retention window (in days) for non-ERROR and blank Level__c logs. */
    private static final Integer STANDARD_RETENTION_DAYS = 30;

    /** Retention window (in days) for ERROR logs. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /**
     * Cron expression for "every day at 02:00":
     * sec min hour day-of-month month day-of-week (year optional).
     */
    @TestVisible
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';

    /** Job name shown under Setup > Scheduled Jobs. */
    @TestVisible
    private static final String NIGHTLY_JOB_NAME = 'Log purge (nightly)';

    /**
     * @description No-argument constructor. The platform instantiates the class
     *              itself when the scheduled time is reached, so this
     *              constructor must not require arguments.
     */
    public LogPurgeJob() {}

    /**
     * @description Entry point invoked by the scheduler on each run.
     * @param ctx Scheduling context provided by the platform. May be null when
     *            the method is invoked directly from a test.
     */
    public void execute(SchedulableContext ctx) {
        purgeExpiredLogs();
    }

    /**
     * @description Deletes FB_Integration_Log__c records that have passed their
     *              retention window.
     *
     *              Governor-limit safety: Apex allows at most 10,000 rows per
     *              DML statement/transaction, so the query is capped at that
     *              number. If a large backlog exists, the oldest records are
     *              purged first (ORDER BY CreatedDate) and the remainder is
     *              handled by the next nightly run instead of the job failing
     *              with a LimitException.
     */
    @TestVisible
    private static void purgeExpiredLogs() {
        Datetime standardCutoff = Datetime.now().addDays(-STANDARD_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> expiredLogs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :standardCutoff AND (Level__c = null OR Level__c != 'ERROR'))
               OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
            ORDER BY CreatedDate
            LIMIT 10000
        ];

        if (expiredLogs.isEmpty()) {
            return;
        }

        // allOrNone = false: a single row lock (e.g. a record still being
        // written by the integration) fails only that row and does not abort
        // the whole purge run.
        Database.delete(expiredLogs, false);

        System.debug(
            LoggingLevel.INFO,
            'LogPurgeJob deleted ' + expiredLogs.size() + ' FB_Integration_Log__c record(s)'
        );
    }

    /**
     * @description Schedules this job to run every day at 02:00 under the job
     *              name "Log purge (nightly)".
     *              Note: System.schedule throws if a scheduled job with the
     *              same name already exists, so call this once per org (e.g.
     *              from a post-deploy step).
     * @return The Id of the resulting CronTrigger record, as returned by
     *         System.schedule.
     */
    public static Id scheduleNightly() {
        return System.schedule(NIGHTLY_JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }
}
