/**
 * Creates an onboarding Task for the owner of every newly created customer
 * Account.
 *
 * Runs in the Account after insert context via the Trigger Actions Framework,
 * registered by the Trigger_Action__mdt record TA_Account_CreateOnboardingTask
 * (Order__c = 10, After_Insert__c = Account).
 *
 * Behavior:
 *  - A Task is created only when the new Account's Type is
 *    "Customer - Direct" or "Customer - Channel". Accounts of any other type,
 *    or with a blank type, are ignored.
 *  - Only account creation is handled: the class implements
 *    TriggerAction.AfterInsert exclusively, so it can never fire in other
 *    trigger contexts.
 *  - All Tasks for one trigger execution are accumulated in memory and
 *    inserted with a single DML statement, keeping the action bulk-safe for
 *    200-record data loads.
 *  - No DML is performed at all when no account in the batch qualifies.
 *  - No SOQL is required: WhatId and OwnerId are taken directly from the
 *    in-memory records, which are fully populated in the after insert context.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    /** Account Types that qualify for an onboarding Task. */
    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    /** Days after account creation when the onboarding Task is due. */
    private static final Integer DUE_DATE_OFFSET_DAYS = 7;

    /** Subject applied to every onboarding Task. */
    private static final String TASK_SUBJECT = 'Onboard new customer';

    /** Required Task status. */
    private static final String TASK_STATUS = 'Not Started';

    /** Required Task priority. */
    private static final String TASK_PRIORITY = 'Normal';

    /**
     * Trigger Actions Framework after-insert entry point.
     *
     * @param triggerNew the Accounts created in this trigger execution.
     */
    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        // Compute once per execution rather than once per record.
        Date activityDate = Date.today().addDays(DUE_DATE_OFFSET_DAYS);
        List<Task> onboardingTasks = new List<Task>();

        for (SObject record : triggerNew) {
            Account account = (Account) record;

            // Blank Type (or any non-customer type) never qualifies.
            if (account.Type == null || !ONBOARDING_ACCOUNT_TYPES.contains(account.Type)) {
                continue;
            }

            onboardingTasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = activityDate,
                    Status = TASK_STATUS,
                    Priority = TASK_PRIORITY
                )
            );
        }

        // Exactly one DML statement per trigger execution, and only when at
        // least one account qualified.
        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }
}
